import type { SlotJackpotTier, SlotRoundResult } from '../models/SlotRound';

/**
 * 純資料流程規劃：只描述「該加入哪些 Task、依什麼順序」，不 import cc／View／具體 Task class，
 * 也不執行任何演出。`SpinResultHandler` 依這份規劃結果組裝實際 Task；Node 測試環境可以直接
 * 用真實 fixture 驗證這裡的決策，不需要假的 Cocos 引擎。
 */
export type SpinFlowStep =
    | { readonly kind: 'collectWin'; readonly mainMult: number; readonly spinWin: number }
    | { readonly kind: 'scatterWin' }
    | { readonly kind: 'closeDoor' }
    // 中彩池時 balanceAfter 是扣掉彩池的餘額 演彩池時才補上
    | { readonly kind: 'finishSpin'; readonly spinWin: number; readonly balanceAfter: string }
    | { readonly kind: 'winAnimation'; readonly spinWin: number }
    // 演完彩池 贏分改成 winAfter 有 balanceAfter 才更新餘額 免費遊戲前演時局還沒結束 不動餘額
    | { readonly kind: 'jackpot'; readonly tier: SlotJackpotTier; readonly amount: number; readonly winAfter: number; readonly balanceAfter?: string }
    | { readonly kind: 'endSpin' }
    | { readonly kind: 'winFreeGamePopup'; readonly freeRoundCount: number }
    | { readonly kind: 'enterFreeGame'; readonly freeRoundCount: number }
    | { readonly kind: 'playFreeRound'; readonly freeRoundIndex: number }
    /** 玩家端 API：免費遊戲每一轉在播放時才向後端要，一直播到局結束，結束後再排收尾 */
    | { readonly kind: 'playFreeGame' }
    | { readonly kind: 'fgDelay' }
    | { readonly kind: 'exitFreeGame' };

/**
 * 依 SlotRoundResult 規劃一局 Spin 完整流程。
 *
 * willEnterFreeGame 需要外部傳入：是否進 FG 還要看「當下盤面實際 scatter 數」跟「玩家是否
 * pending buy feature」這兩個依賴即時畫面／外部狀態的條件，規劃器本身只認後端權威資料
 * （SlotRoundResult.freeSpinTriggered／freeRounds），不會自己猜盤面。
 */
export function planSpinFlow(roundResult: SlotRoundResult, willEnterFreeGame: boolean): SpinFlowStep[] {
    const steps: SpinFlowStep[] = [];
    const mainMult = roundResult.multiplier || 0;
    const jackpotWin = jackpotWinOf(roundResult);
    // 一般贏分 不含彩池 大獎級別與報獎都看它
    // 後端 wt 定義是含彩池的整局贏分 這裡刻意不含 彩池金額在演彩池時才加進贏分與餘額
    const spinWin = (Number(roundResult.totalWin) || 0) - jackpotWin;

    if (mainMult > 0 && spinWin > 0) {
        steps.push({ kind: 'collectWin', mainMult, spinWin });
    }

    if (willEnterFreeGame) {
        // 同一局有贏分 先報獎 彩池在進免費遊戲之前演
        steps.push({ kind: 'winAnimation', spinWin });
        appendJackpotStep(steps, roundResult, spinWin, false);
        steps.push({ kind: 'scatterWin' });
        appendFreeGameSteps(steps, roundResult, spinWin);
        return steps;
    }

    steps.push({ kind: 'finishSpin', spinWin, balanceAfter: balanceBeforeJackpot(roundResult, jackpotWin) });
    steps.push({ kind: 'winAnimation', spinWin });
    appendJackpotStep(steps, roundResult, spinWin, true);
    steps.push({ kind: 'endSpin' });
    return steps;
}

/**
 * 這一局彩池派彩金額
 *
 * @param roundResult 這一局的結果
 * @returns 沒中彩池是 0
 */
export function jackpotWinOf(roundResult: SlotRoundResult): number {
    const jackpot = roundResult.jackpot;
    return jackpot?.won && jackpot.tier ? Number(jackpot.payout) || 0 : 0;
}

function balanceBeforeJackpot(roundResult: SlotRoundResult, jackpotWin: number): string {
    return jackpotWin > 0 ? String(Number(roundResult.balanceAfter) - jackpotWin) : roundResult.balanceAfter;
}

function appendFreeGameSteps(steps: SpinFlowStep[], roundResult: SlotRoundResult, spinWin: number): void {
    const lazy = roundResult.freeSpinsTotal !== undefined;
    const freeRoundCount = roundResult.freeSpinsTotal ?? roundResult.freeRounds.length;
    if (freeRoundCount === 0) {
        // 彩池已在前面演過 這裡直接用含彩池的最終餘額
        steps.push({ kind: 'finishSpin', spinWin: spinWin + jackpotWinOf(roundResult), balanceAfter: roundResult.balanceAfter });
        steps.push({ kind: 'endSpin' });
        return;
    }

    steps.push({ kind: 'closeDoor' });
    steps.push({ kind: 'winFreeGamePopup', freeRoundCount });
    steps.push({ kind: 'enterFreeGame', freeRoundCount });
    if (lazy) {
        steps.push({ kind: 'playFreeGame' });
        return;
    }

    for (let i = 0; i < freeRoundCount; i++) {
        steps.push({ kind: 'playFreeRound', freeRoundIndex: i });
        if (i < freeRoundCount - 1) steps.push({ kind: 'fgDelay' });
    }
    steps.push({ kind: 'exitFreeGame' });
}

function appendJackpotStep(steps: SpinFlowStep[], roundResult: SlotRoundResult, spinWin: number, roundEnds: boolean): void {
    const jackpot = roundResult.jackpot;
    if (!jackpot?.won || !jackpot.tier) return;
    const amount = jackpotWinOf(roundResult);
    steps.push({ kind: 'jackpot', tier: jackpot.tier, amount, winAfter: spinWin + amount, ...(roundEnds ? { balanceAfter: roundResult.balanceAfter } : {}) });
}
