// 玩家端 API 的推播通道 規格第 6 章 下注走 HTTP 這條只收推播 斷線不影響下注

// 伺服器推來的訊框 data 只有部分訊息有
export interface SlotApiPushFrame<T = unknown> {
    type: string;
    seq: number;
    ts: number;
    data?: T;
}

export interface SlotWebSocketClientOptions {
    // entry 回應的 ws
    url: string;
    // 網址上的 t 跟 HTTP 同一把
    token: string;
    // 重連前先做的事 回 false 代表不要再重連
    beforeReconnect?: () => Promise<boolean>;
}

// 心跳間隔 規格要求每 25 秒送一次 ping
const HEARTBEAT_MS = 25000;
// 重連退避 1 2 4 8 秒 上限 30 秒 加減 20% 抖動
const BACKOFF_BASE_MS = 1000;
const BACKOFF_MAX_MS = 30000;
const BACKOFF_JITTER = 0.2;
const SOCKET_OPEN = 1;

/**
 * 組出帶 token 的連線網址。
 *
 * @remarks 原生的 URL 是假 DOM 的 polyfill 沒有 searchParams 會丟錯 所以用字串組。
 * @param url entry 回應的 ws。
 * @param token 網址上的 t。
 * @returns 帶 `token` 參數的網址 已經有 token 就原樣回傳。
 */
export function buildSlotApiWebSocketUrl(url: string, token: string): string {
    if (!token) return url;
    const [path, query = ''] = url.split('?');
    const params = query.split('&').filter(Boolean);
    if (params.some((param) => param.startsWith('token='))) return url;
    params.push(`token=${encodeURIComponent(token)}`);
    return `${path}?${params.join('&')}`;
}

export default class SlotWebSocketClient {
    private socket: WebSocket | null = null;
    private heartbeatTimer: ReturnType<typeof setInterval> | null = null;
    private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    private reconnectAttempts = 0;
    // 主動關閉 或 收到被踢 都不重連
    private stopped = false;
    private readonly frameListeners = new Set<(frame: SlotApiPushFrame) => void>();
    private readonly stateListeners = new Set<(open: boolean) => void>();

    constructor(private readonly options: SlotWebSocketClientOptions) {}

    /**
     * 目前連線是不是開著。
     *
     * @returns 開著為 true。
     */
    get isOpen(): boolean {
        return this.socket?.readyState === SOCKET_OPEN;
    }

    /**
     * 建立連線 已經有連線或已停止就不做事。
     */
    connect(): void {
        if (this.stopped || this.socket) return;
        const url = buildSlotApiWebSocketUrl(this.options.url, this.options.token);
        console.log('[SlotWSClient] connect', this.options.url);
        const socket = new WebSocket(url);
        this.socket = socket;
        socket.onopen = () => {
            console.log('[SlotWSClient] open');
            this.reconnectAttempts = 0;
            this.startHeartbeat();
            for (const listener of this.stateListeners) listener(true);
        };
        socket.onmessage = (event) => this.handleMessage(event.data);
        socket.onclose = () => this.handleClose(socket);
    }

    /**
     * 主動關閉 不再重連。
     */
    close(): void {
        this.stopped = true;
        this.clearReconnectTimer();
        this.stopHeartbeat();
        const socket = this.socket;
        this.socket = null;
        socket?.close();
    }

    /**
     * 訂閱伺服器推來的訊框。
     *
     * @param listener 收到訊框時呼叫 pong 不會傳進來。
     */
    onFrame(listener: (frame: SlotApiPushFrame) => void): void {
        this.frameListeners.add(listener);
    }

    /**
     * 訂閱連線開關。
     *
     * @param listener 連上時傳 true 斷線時傳 false。
     */
    onState(listener: (open: boolean) => void): void {
        this.stateListeners.add(listener);
    }

    private handleMessage(raw: unknown): void {
        let frame: SlotApiPushFrame;
        try {
            frame = JSON.parse(String(raw));
        } catch {
            return;
        }
        if (!frame || typeof frame.type !== 'string') return;
        console.log('[SlotWSClient][Response]', frame);
        if (frame.type === 'pong') return;
        // 被踢之後伺服器會關線 這條不能重連
        if (frame.type === 'session.kicked') {
            this.stopped = true;
        }
        for (const listener of this.frameListeners) listener(frame);
    }

    private handleClose(socket: WebSocket): void {
        if (this.socket !== socket) return;
        this.socket = null;
        this.stopHeartbeat();
        console.log('[SlotWSClient] closed');
        for (const listener of this.stateListeners) listener(false);
        this.scheduleReconnect();
    }

    private scheduleReconnect(): void {
        if (this.stopped || this.reconnectTimer) return;
        this.reconnectAttempts += 1;
        const base = Math.min(BACKOFF_MAX_MS, BACKOFF_BASE_MS * 2 ** (this.reconnectAttempts - 1));
        const delay = base * (1 + (Math.random() * 2 - 1) * BACKOFF_JITTER);
        console.log('[SlotWSClient] reconnecting', { attempt: this.reconnectAttempts, delayMs: Math.round(delay) });
        this.reconnectTimer = setTimeout(() => {
            this.reconnectTimer = null;
            void this.reconnect();
        }, delay);
    }

    private async reconnect(): Promise<void> {
        if (this.stopped) return;
        if (this.options.beforeReconnect) {
            let proceed = true;
            try {
                proceed = await this.options.beforeReconnect();
            } catch {
                proceed = true;
            }
            if (!proceed) this.stopped = true;
        }
        if (this.stopped) return;
        try {
            this.connect();
        } catch (error) {
            console.error('[SlotWSClient] reconnect failed', error);
        }
        // 建立連線就丟錯時不會有 onclose 沒有連線就排下一次
        if (!this.socket) this.scheduleReconnect();
    }

    private startHeartbeat(): void {
        this.stopHeartbeat();
        this.heartbeatTimer = setInterval(() => {
            if (!this.isOpen) return;
            const frame = { type: 'ping' };
            console.log('[SlotWSClient][Request]', frame);
            this.socket!.send(JSON.stringify(frame));
        }, HEARTBEAT_MS);
    }

    private stopHeartbeat(): void {
        if (this.heartbeatTimer) clearInterval(this.heartbeatTimer);
        this.heartbeatTimer = null;
    }

    private clearReconnectTimer(): void {
        if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
        this.reconnectTimer = null;
    }
}
