import { startSimpleMock } from "../simple-mock";
import { installSlotApiHttpMock, uninstallSlotApiHttpMock } from "./slot-api-mock";
import { installSlotApiWebSocketMock, uninstallSlotApiWebSocketMock } from "./slot-push-mock";

/**
 * 啟動假後端：註冊玩家端 API 的路由，裝上 fetch／XHR 替身讓路由攔得到請求，並裝上推播通道的 WebSocket 代理，重複呼叫是安全的。
 *
 * @returns 裝好之後 resolve。
 */
export async function startGameMock(): Promise<void> {
    installSlotApiHttpMock();
    installSlotApiWebSocketMock();
    startSimpleMock();
}

/**
 * 離開遊戲時拆掉假後端的路由與 WebSocket 代理，不留給下一款遊戲。
 *
 * `simple-mock` 的 fetch／XHR 替身不拆：路由清掉之後請求都原樣放行，留著不影響別款遊戲的資料。
 */
export function stopGameMock(): void {
    uninstallSlotApiHttpMock();
    uninstallSlotApiWebSocketMock();
}
