// ============================================================
// SlotApiTypes.ts（1001 荷魯斯之眼）
// 玩家端 API v8.1 的線上格式（後端串接包 2026-11-02，slotgame `docs/遊戲前端串接包-20261102/`）。
//
// 請求 body 與成功回應的 `data` 是短 key（v7.0 起）；錯誤信封與 history 的鍵維持完整英文。
// 這裡只描述線上長什麼樣子，轉成前端模型在 SlotRoundMapper／SlotHistoryMapper，
// Handler／Task／View 不得直接讀這些型別。
// ============================================================

/** 回應信封：成功時 `code` 是 0、內容在 `data`；業務錯誤也是 HTTP 200，`code` 是錯誤碼（附錄 A） */
export interface SlotApiEnvelope<T> {
    code: number;
    data?: T;
    message?: string;
    trace_id?: string;
    /** 只在 entry 回 4022 時出現：幾秒後再打 entry */
    retry_after?: number;
    /** 只在 4016 時出現：客服單號（局號前 8 碼） */
    support_ref?: string;
    /** 只在 4023 時出現：最新一步的 `sid`，當下一個請求的 `id` */
    latest_step_id?: string;
}

/** 前端會分流處理的錯誤碼（規格附錄 A） */
export const SLOT_API_CODE = {
    OK: 0,
    // 線路不存在或停用
    LINE_CLOSED: 4001,
    // 玩家不存在
    PLAYER_NOT_FOUND: 4002,
    // 遊戲未授權給線路
    GAME_NOT_ALLOWED: 4003,
    NOT_FOUND: 4004,
    BAD_REQUEST: 4005,
    // 幣別不符
    CURRENCY_MISMATCH: 4010,
    TOKEN_REJECTED: 4011,
    LIMIT_OR_FROZEN: 4013,
    INSUFFICIENT_BALANCE: 4014,
    BET_VOID: 4015,
    NEEDS_SUPPORT: 4016,
    // 玩家被凍結
    FROZEN: 4018,
    STEP_WRITING: 4017,
    MODE_CLOSED: 4019,
    AWAITING_SELECT: 4021,
    PROCESSING: 4022,
    NOT_LATEST_STEP: 4023,
    RATE_LIMITED: 4029,
    BUSY: 4030,
    INTERNAL: 4500,
    MAINTENANCE: 4503,
} as const;

/**
 * 錯誤的來源：`business` 是信封帶了非 0 的 `code`；`unauthorized` 是沒有 `code` 的 HTTP 401（session 失效，
 * 再打一次 entry）；`http` 是其他沒有 `code` 的 HTTP 錯誤（503 等）；`network` 是連不上或逾時。
 */
export type SlotApiErrorKind = 'business' | 'unauthorized' | 'http' | 'network';

/** 玩家端 API 的失敗：業務錯誤碼、HTTP 狀態，以及錯誤信封附帶的欄位 */
export class SlotApiHttpError extends Error {
    /**
     * @param kind 錯誤的來源。
     * @param code 業務錯誤碼（附錄 A）；沒有 `code` 的 401、503、網路錯誤是 0。
     * @param message 錯誤說明，只給人看。
     * @param httpStatus HTTP 狀態碼；網路錯誤是 0。
     * @param supportRef 4016 的客服單號。
     * @param latestStepId 4023 的最新一步。
     * @param retryAfterSec 429 的 `Retry-After` 或 entry 4022 的 `retry_after`（秒）。
     */
    constructor(
        public readonly kind: SlotApiErrorKind,
        public readonly code: number,
        message: string,
        public readonly httpStatus: number = 0,
        public readonly supportRef?: string,
        public readonly latestStepId?: string,
        public readonly retryAfterSec?: number
    ) {
        super(message);
        this.name = 'SlotApiHttpError';
    }
}

/** 步驟狀態代碼（規格 §4.5）：`st` 是這一步，`nst` 是下一步；`nst` 是 1 代表局結束 */
export const STEP_STATE = {
    BASE_SPIN: 1,
    BASE_TUMBLE: 4,
    BASE_RESPIN: 5,
    FREE_SPIN: 21,
    FREE_TUMBLE: 22,
    FREE_RESPIN: 23,
    SELECT: 31,
} as const;

/**
 * 這一步之後局還沒結束
 *
 * @param step 步驟物件
 * @returns `nst` 不是一般轉 true
 */
export function isRoundInProgress(step: Pick<SlotApiStep, 'nst'>): boolean {
    return step.nst !== STEP_STATE.BASE_SPIN;
}

/** 免費遊戲轉數：只在這一局到這一步為止授過免費遊戲時出現，值在播授轉事件的那一步才變 */
export interface SlotApiFreeSpins {
    /** 剩餘轉數；撞上限提早結束時是沒打的轉數 */
    s: number;
    /** 到這一步為止已經播出的獲授總轉數 */
    ts: number;
    /** 這一步自己的盤面裡授轉事件的合計（`FE` 的 `rd`、`RT` 的 `awd`） */
    nosa: number;
}

/** 一筆中獎（渲染契約 `wn`）：`CL` 全盤計數、`SC` 散射賠付、`JP` 彩池 */
export interface SlotApiWin {
    k: string;
    /** 中獎符號；彩池是 0 */
    sy: number;
    /** 命中格的位置（全窗格編號，見 SlotGridDecoder） */
    c: number[];
    /** 賠付，底注倍數（還沒乘球倍數） */
    p: string;
    /** 等於 `p` */
    w: string;
    /** 彩池層級 `"1"`–`"4"`（Mini／Minor／Major／Grand），只有 `JP` 有 */
    tr?: string;
}

/** 盤面事件：陣列順序就是播放順序，`d` 的鍵依事件代碼而定 */
export interface SlotApiEvent {
    t: string;
    d?: Record<string, unknown>;
}

/** 一張盤面（渲染契約 `sg[]`）：空的、預設的鍵不出現 */
export interface SlotApiBoard {
    /** 盤面類型：`B` 初盤、`C` 連消後的盤面 */
    t: string;
    /** 每軸由上到下的符號 id，含最上面不計分的隱藏列（全窗格） */
    rl: number[][];
    /** 格子標記：鍵是格子位置，`x` 是球的面值（和符號 id 一致） */
    co?: Record<string, { x: number }>;
    wn?: SlotApiWin[];
    /** 這張盤面的贏分，底注倍數 */
    bm?: string;
    e?: SlotApiEvent[];
}

/** 一步的盤面結果（步驟物件的 `r`、history 細單的 `result`） */
export interface SlotApiResult {
    /** schema 版本；本款是 2（`eyeofhorus.result.v2`） */
    ver: number;
    sg: SlotApiBoard[];
}

/** 步驟物件：bet／select 的回應、entry／status 的 `ls`（規格 §5.2） */
export interface SlotApiStep {
    /** 這一步的編號（`{round_id}:{seq}:{index}`），下一個請求原樣放進 `id`；沒玩過時是空字串 */
    sid: string;
    st: number;
    nst: number;
    /** 本局的 Bet Size／Bet Level，續打要送這兩個值 */
    cs: string;
    ml: number;
    /** 本局實際扣款額 */
    tb: string;
    bt?: string;
    et?: string;
    vr?: string;
    /** 這一步之後要顯示的餘額；局還沒結束時是開局扣款後的值，最後一步才是派彩後 */
    bl: string;
    /** 這一步的贏分 */
    ctw: string;
    /** 這一轉到這一步為止的累計贏分 */
    tw: string;
    /** 整局到這一步為止的累計贏分；局結束那一步＝實際派彩 */
    aw: string;
    fs?: SlotApiFreeSpins;
    r: SlotApiResult | null;
    /** 延續狀態，只在 entry／status 的 `ls`、而且局還沒結束時出現 */
    gs?: Record<string, unknown>;
}

/** `POST /player/entry` 的 `data`（規格 §5.1） */
export interface SlotApiEntry {
    /** 最近一步，永遠有值；沒玩過是合成的預設步驟（`sid` 是空字串） */
    ls: SlotApiStep;
    /** 幣別 */
    cc: string;
    /** 幣別小數位 */
    cd: number;
    /** 餘額；查不到時是空字串 */
    bl: string;
    /** 商戶 launch 帶的語系，原樣轉交 */
    lg: string;
    ws: string;
    lb: string;
    ca: string;
    /** Base Bet：每單位幾幣，底注＝cs × ml × bb */
    bb: number;
    cs: string[];
    ml: number[];
    /** 伺服器選好的預選值 */
    pre: { cs: string; ml: number };
    buy?: { id: string; m: string; vr?: string }[];
    xb?: { id: string; m: string }[];
    vs?: { id: string; nm: string }[];
    gid: string;
    rtp: string;
    /** 整局贏分上限，底注倍數 */
    maxwm?: string;
    /** 大獎門檻（big／mega／super），底注倍數；`"0"` 是沒設定 */
    wt: { bw: string; mgw: string; smgw: string; epw: string };
}

/** `POST /player/bet` 的請求（規格 §5.2）：續打送本局的 `cs`／`ml`，不帶 `bt`／`et`／`vr` */
export interface SlotApiBetRequest {
    /** 上一步的 `sid`；開新局送 entry 的 `ls.sid`（沒玩過是空字串） */
    id: string;
    cs: string;
    ml: number;
    bt?: string;
    et?: string;
    vr?: string;
}

/** history 的母單（列表的一列、單局的 `round`） */
export interface SlotApiHistoryRound {
    round_id: string;
    game_id: string;
    bet_amount: string;
    payout_amount: string;
    currency: string;
    /** 細單數：一整轉一張 */
    detail_count: number;
    feature_flags: string[];
    settled_at_unix: number;
    bet_size: string;
    bet_level: number;
    /** 底注金額；細單 `result` 裡的倍數乘它就是金額 */
    base_bet_amount: string;
    spin_type: string;
    tier_id: string;
    variant?: string;
}

/** `GET /player/history`（列表模式）的 `data` */
export interface SlotApiHistoryList {
    rounds: SlotApiHistoryRound[];
    page: number;
    total_pages: number;
    total_items: number;
    total_bet: string;
    total_payout: string;
}

/** 單局重播的一張細單：一整轉，`result.sg` 是這一轉各步的盤面依序接起來 */
export interface SlotApiHistoryDetail {
    detail_id: string;
    seq: number;
    detail_type: string;
    bet_amount: string;
    payout_amount: string;
    win_multiplier: string;
    result: SlotApiResult | null;
}

/** `GET /player/history?round_id=`（單局模式）的 `data` */
export interface SlotApiHistoryRoundDetail {
    round: SlotApiHistoryRound;
    details: SlotApiHistoryDetail[];
}

/** `GET /player/jackpots` 的 `data`（規格 §5.7） */
export interface SlotApiJackpotsResponse {
    pools: {
        pool_id: string;
        current_value: string;
        currency: string;
        /** 層級 1–4 */
        tier: number;
        pricing_mode: string;
        /** 機率最高的底注 */
        reference_bet?: string;
    }[];
}

/** 彩池等級（層級 1–4 依序） */
export type SlotApiJackpotTier = 'MINI' | 'MINOR' | 'MAJOR' | 'GRAND';

export interface SlotApiJackpotPoolEntry {
    tier: SlotApiJackpotTier;
    /** 十進位字串 */
    amount: string;
}

/** 常駐獎池條讀的水位快照 */
export interface SlotApiJackpotPoolSnapshot {
    game_code: string;
    currency: string;
    pool_group_id: string;
    pools: SlotApiJackpotPoolEntry[];
    as_of_ms: number;
}
