import type { SlotColumn, SlotGrid, SlotGridLayout } from '../models/SlotGrid';
import type { SlotAwardPosition } from '../models/SlotRound';
import type { SlotBoardDamp } from './GridLayoutConfig';

/**
 * 純資料 decoder：把後端的全窗格盤面（`rl`，每軸含隱藏列）拆成可見盤，
 * 以及把格子位置換回可見盤座標。不解析遊戲 Symbol。
 */
export class SlotGridDecoder {
    /**
     * @param layout 可見盤的形狀。
     * @param damp 每軸上下各有幾格隱藏列。
     */
    constructor(
        private readonly layout: SlotGridLayout,
        private readonly damp: SlotBoardDamp
    ) {}

    /**
     * 把一張盤面的 `rl` 解成前端用的盤面，過程中先驗證維度是否相符。
     *
     * 維度對不起來時丟例外而不是默默修正：那代表本地登記的盤面形狀跟後端不同步，硬解下去會整盤錯位。
     *
     * @param rl 每軸由上到下的符號 id，含隱藏列。
     * @returns 可見盤；每欄另外帶隱藏列的符號。
     * @throws 欄數或任一欄的格數跟設定不符時丟 RangeError。
     */
    decode(rl: readonly (readonly number[])[]): SlotGrid {
        if (rl.length !== this.layout.columns) {
            throw new RangeError(`Board column count mismatch: rl=${rl.length}, layout=${this.layout.columns}`);
        }
        const { top, bottom } = this.damp;
        const visible = this.layout.visibleRows;
        const columns: SlotColumn[] = rl.map((full, index) => {
            if (full.length !== top + visible + bottom) {
                throw new RangeError(`Board column ${index} has ${full.length} rows; expected ${top} + ${visible} + ${bottom}`);
            }
            return {
                index,
                symbolIds: full.slice(top, top + visible),
                dampTop: top > 0 ? full[top - 1] : undefined,
            };
        });
        return { layout: { ...this.layout }, columns };
    }

    /**
     * 把格子位置換成可見盤座標。
     *
     * 位置是「全窗格逐軸加總」的編號：每軸 6 格，位置 = 軸 × 6 + 列，列含隱藏列。
     *
     * @param rl 位置所在那張盤面的 `rl`，用它的每軸長度算加總。
     * @param position 格子位置。
     * @returns 可見盤座標；落在隱藏列或超出範圍時 null。
     */
    toCell(rl: readonly (readonly number[])[], position: number): SlotAwardPosition | null {
        let start = 0;
        for (let col = 0; col < rl.length; col++) {
            const length = rl[col].length;
            if (position < start + length) {
                const row = position - start - this.damp.top;
                return row >= 0 && row < this.layout.visibleRows ? { col, row } : null;
            }
            start += length;
        }
        return null;
    }
}
