/**
 * 大廳寫進 `globalThis.__subGameData__` 的資料 只收這個遊戲讀寫的欄位
 * 權威定義在 base 的 subgame/SubGameConfig.ts 欄位改名時兩邊要一起改
 */
export interface SubGameData {
    /** 子遊戲 Bundle 的 CDN 來源位址 */
    cdnBase: string;

    /** 大廳認定的 gameId */
    gameId: string;

    /** 本次載入的版本 來源不明的快取可能沒有 */
    version?: string;

    /** 離開前的清理鉤子 由子遊戲註冊 大廳卸載前呼叫 */
    beforeExit?: () => Promise<void>;
}

// 子遊戲跟大廳 殼頁溝通的接口都集中在這裡 其他地方不要直接碰 globalThis 的 __subGame*
// 這份程式碼跨到大廳（entry）那個獨立 Creator 專案裡執行 沒辦法直接 import
// 只能透過大廳常駐節點在載入前掛好的 globalThis 函式呼叫回去 詳見 entry 的 assets/base/subgame/SubGame.ts
// 下面的名稱與簽名以 SubGame.ts 的 SubGameGlobalScope 為準 改名時兩邊要一起改
// 網頁版放在殼頁 iframe 裡 改用 postMessage 跟殼頁溝通 協定見 yota-remote-bundles 的 shell.html
type SubGameGlobalScope = typeof globalThis & {
    __subGameData__?: SubGameData;
    __subGameExit__?: () => void | Promise<void>;
    __subGameShowSystemMenu__?: () => Promise<void>;
    __subGameShowAutoPlaySelector__?: () => Promise<number | null>;
    __subGameFixedRatio__?: boolean;
    __subGameEnterStartTime__?: number;
    __subGameEntered__?: () => void;
};

const scope = (): SubGameGlobalScope => globalThis as SubGameGlobalScope;

/**
 * 取大廳帶進來的子遊戲資料
 *
 * @returns 有大廳時回資料 獨立 Preview 或直接開 bundle 時回 undefined
 */
export function getSubGameData(): SubGameData | undefined {
    return scope().__subGameData__;
}

/**
 * 是不是放在殼頁的 iframe 裡
 *
 * @returns 在 iframe 裡為 true
 */
export function inShell(): boolean {
    return typeof window !== 'undefined' && !!window.parent && window.parent !== window;
}

/**
 * 送訊息給殼頁 不在殼頁裡就不送
 *
 * @param type 訊息類型
 * @param payload 訊息內容
 */
export function postToShell(type: string, payload: object = {}): void {
    if (inShell()) window.parent.postMessage({ source: 'game', type, payload }, '*');
}

/**
 * 監聽殼頁送來的訊息 不在殼頁裡就不監聽
 *
 * @param handler 收到殼頁訊息時呼叫 帶訊息類型與內容
 * @returns 取消監聽的函式
 */
export function onShellMessage(handler: (type: string, payload: any) => void): () => void {
    if (!inShell()) return () => {};
    const listener = (event: MessageEvent): void => {
        if (event.source !== window.parent || event.data?.source !== 'host-shell') return;
        handler(event.data.type, event.data.payload);
    };
    window.addEventListener('message', listener);
    return () => window.removeEventListener('message', listener);
}

/**
 * 不經確認直接回大廳 token 失效 被踢這類不能再玩的情況用
 *
 * @remarks 原生大廳用 `__subGameExit__` 網頁殼頁送 `leave` 兩邊都沒有時只印警告
 */
export function exitToLobby(): void {
    const exit = scope().__subGameExit__;
    if (exit) {
        void exit();
        return;
    }
    if (inShell()) {
        postToShell('leave');
        return;
    }
    console.warn('[大廳橋接] exitToLobby 沒有大廳可以回 獨立測試模式略過');
}

/**
 * 開大廳的系統選單
 *
 * @returns 選單關掉之後 resolve 沒接上大廳時印警告後直接 resolve
 */
export async function showSystemMenu(): Promise<void> {
    const show = scope().__subGameShowSystemMenu__;
    if (!show) {
        console.warn('[大廳橋接] showSystemMenu 未接上大廳 獨立測試模式略過');
        return;
    }
    await show();
}

/**
 * 開大廳的自動旋轉局數選擇
 *
 * @returns 選到的局數 負數代表無限 取消是 null 沒接上大廳時印警告並回 undefined
 */
export async function showAutoPlaySelector(): Promise<number | null | undefined> {
    const show = scope().__subGameShowAutoPlaySelector__;
    if (!show) {
        console.warn('[大廳橋接] showAutoPlaySelector 未接上大廳 獨立測試模式略過');
        return undefined;
    }
    return show();
}

/**
 * 大廳是否判斷這個網頁要用固定比例顯示
 *
 * @returns 固定比例為 true
 */
export function isFixedRatio(): boolean {
    return scope().__subGameFixedRatio__ === true;
}

/**
 * 大廳按下進場那一刻的時間戳
 *
 * @returns 毫秒時間戳 沒有大廳時 undefined
 */
export function getEnterStartTime(): number | undefined {
    const time = scope().__subGameEnterStartTime__;
    return typeof time === 'number' ? time : undefined;
}

/** 通知大廳已經進到遊戲 沒有大廳就略過 */
export function notifyEntered(): void {
    scope().__subGameEntered__?.();
}
