import { GameNetHandler } from './GameNetHandler';

// jackpot.updated 的 data 每項是一個池 只推有變的
export interface SlotApiJackpotUpdatedData {
    pools: { pool_id: string; tier: number; current_value: string; currency: string }[];
}

// 彩池金額變了
export class JackpotUpdatedHandler extends GameNetHandler<SlotApiJackpotUpdatedData> {
    public readonly key = 'jackpot.updated';

    constructor(private readonly onUpdated: (data: SlotApiJackpotUpdatedData) => void) {
        super();
    }

    public handle(payload: SlotApiJackpotUpdatedData): void {
        if (payload && Array.isArray(payload.pools)) this.onUpdated(payload);
    }
}

// 同玩家同遊戲在別處進場 或商戶關閉了 session
export class SessionKickedHandler extends GameNetHandler<undefined> {
    public readonly key = 'session.kicked';

    constructor(private readonly onKicked: () => void) {
        super();
    }

    public handle(): void {
        this.onKicked();
    }
}

// session 剩不到 5 分鐘
export class SessionExpiringHandler extends GameNetHandler<undefined> {
    public readonly key = 'session.expiring';

    constructor(private readonly onExpiring: () => void) {
        super();
    }

    public handle(): void {
        this.onExpiring();
    }
}
