import AppAudio from './AppAudio';

// 'skip' 不播 其餘字串是改播的替代音效路徑 沒有定義的組合視為照播
export type SpeedBehavior = 'skip' | string;

// key 是遊戲自己的音效值 value 是這個效果在各狀態下要怎麼處理
export type SpeedBehaviorTable<TEffect extends string, TMode extends string> = Partial<Record<TEffect, Partial<Record<TMode, SpeedBehavior>>>>;

/** 查表決定要不要播 播什麼 查不到視為照原路徑播放 */
export function playBySpeed<TEffect extends string, TMode extends string>(
    table: SpeedBehaviorTable<TEffect, TMode>,
    key: TEffect,
    mode: TMode,
    bundleName?: string
): void {
    const behavior = table[key]?.[mode];
    if (behavior === 'skip') return;
    AppAudio.getInstance(bundleName).playEffect(behavior ?? (key as string)).catch(() => {});
}

/** loop 版本 查表決定要不要播 */
export function playLoopBySpeed<TEffect extends string, TMode extends string>(
    table: SpeedBehaviorTable<TEffect, TMode>,
    key: TEffect,
    mode: TMode,
    bundleName?: string
): void {
    if (table[key]?.[mode] === 'skip') return;
    AppAudio.getInstance(bundleName).playLoopEffect(key as string).catch(() => {});
}
